package com.bitewise.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="products") public class Product { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="business_id",nullable=false) private Business business; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="category_id") private ProductCategory category; @Column(nullable=false) private String name; @Column(name="icon_key") private String iconKey; @Column(name="selling_price",nullable=false) private BigDecimal sellingPrice; @Column(name="cost_price",nullable=false) private BigDecimal costPrice; @Column(nullable=false) private boolean active=true; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); @Column(name="updated_at",nullable=false) private Instant updatedAt=Instant.now(); public Product(){} public Product(Business b,ProductCategory c,String n,String i,BigDecimal sp,BigDecimal cp){business=b;category=c;name=n;iconKey=i;sellingPrice=sp;costPrice=cp;} public UUID getId(){return id;} public Business getBusiness(){return business;} public ProductCategory getCategory(){return category;} public String getName(){return name;} public String getIconKey(){return iconKey;} public BigDecimal getSellingPrice(){return sellingPrice;} public BigDecimal getCostPrice(){return costPrice;} public boolean isActive(){return active;} public void update(ProductCategory c,String n,String i,BigDecimal sp,BigDecimal cp,boolean a){category=c;name=n;iconKey=i;sellingPrice=sp;costPrice=cp;active=a;updatedAt=Instant.now();}}
